  /* The books: statements, the calendar, the VAT return, the trail (C9.3, C10,
   * E2.3, D4).
   *
   * Three of these carry a decision rather than a label.
   *
   * `acct.stillOpen` and its siblings say how settled a statement's figures
   * are. A profit-and-loss for a month that is still open will be a different
   * number tomorrow, and somebody about to send one to a bank should be told
   * that before they send it rather than afterwards.
   *
   * `acct.outOfBalance` is shown above the figures rather than as a red number
   * inside them, because a red number in a familiar report is exactly what a
   * person scanning it does not see.
   *
   * `vat.preparedNotFiled` is the most important sentence on the tax screen.
   * Nothing in this product files anything, and a screen that looked like the
   * official form would invite somebody to believe otherwise. */

