/** Every string the interface can show. */
export type Key = keyof typeof en;

/**
 * The translate function, as a type a plain module can name.
 *
 * Declared here rather than in `locale.tsx` so that a formatter, a receipt
 * builder or anything else with no React in it can accept one without
 * importing a component file.
 */
/** `{name}` substitution.
 *
 * Deliberately the whole of it: anything needing more than a named placeholder
 * is a sentence that should be its own key.
 *
 * It lives beside the catalogue rather than inside the React provider because
 * it is a property of the strings, not of the rendering. Two non-React callers
 * -- the buying screens' delivery notice and the terminal's "why it cannot
 * sell" -- take a `Translate` and fall back to English when they are given
 * none, and their fallback used to be `(key) => en[key]`, which handed the
 * caller the raw template: a storeman saw "Recorded as {grn}." with the braces
 * still in it. A fallback that does not interpolate is not a translator.
 */
export function interpolate(
  text: string | undefined,
  params?: Record<string, string | number>,
): string {
  // Undefined cannot happen for `en` -- the key type is derived from it -- and
  // reaches here only if a locale table and the fallback are both missing a
  // key, which the compiler already prevents. Empty rather than "undefined" on
  // a screen, for the day somebody defeats it with a cast.
  if (text === undefined) return '';
  if (!params) return text;
  return text.replace(/\{(\w+)\}/g, (whole, name: string) =>
    name in params ? isolate(String(params[name])) : whole,
  );
}

/** U+2068 FIRST STRONG ISOLATE and U+2069 POP DIRECTIONAL ISOLATE. */
const FSI = '⁨';
const PDI = '⁩';

/**
 * Fence a substituted value off from the sentence it lands in.
 *
 * The design system (§6 rule 4) says isolation on a currency or number is not
 * optional, and gives the failure: a total placed next to Arabic text can
 * visually reorder its digits. `.num` carries `unicode-bidi: isolate` for the
 * amounts that get an element of their own — but an amount interpolated INTO a
 * sentence has no element. "فارتفعت تكلفة البضاعة المباعة بمقدار SAR 1,250.00."
 * is one text node, and the bidi algorithm resolves it as one paragraph: the
 * trailing full stop belongs to the Arabic, the amount is a left-to-right run,
 * and where the two meet the punctuation can end up on the wrong side of the
 * number.
 *
 * FSI...PDI is the Unicode-level version of the CSS property, and the only
 * tool available inside a plain string. It says: whatever is between these,
 * work out its own direction and do not let it argue with the text around it.
 *
 * Applied to EVERY substituted value, not only ones that look like numbers.
 * A customer's name, a supplier's reference, a product code and an invoice
 * number are all mixed-script in a shop that trades in two languages, and
 * guessing which of them needs fencing is how the one that does gets missed.
 *
 * The characters are zero-width and invisible. They do not affect a comparison
 * a person makes by eye, and the tests that assert on exact output strip them
 * with `plain()` so an assertion says what it means.
 */
function isolate(value: string): string {
  if (value === '') return value;
  return FSI + value + PDI;
}

/**
 * The same text without its isolation marks.
 *
 * For a test asserting on exact output, and for anywhere a string is compared
 * or measured rather than displayed. Never for rendering: stripping these puts
 * the reordering back.
 */
export function plain(text: string): string {
  return text.split(FSI).join('').split(PDI).join('');
}

/** English, for a caller with no locale in scope.
 *
 * A receipt printer, a test, or a pure function called outside a component.
 * The same shape a real `t` has, so a function taking `Translate` behaves
 * identically whether it was given one or not. */
export const plainEnglish: Translate = (key, params) =>
  interpolate(en[key], params);

export type Translate = (
  key: Key,
  params?: Record<string, string | number>,
) => string;

/**
 * The Arabic catalogue.
 *
 * `Record<Key, string>` rather than a partial: a key added to `en` without an
 * Arabic string is a compile error, not a screen that silently falls back to
 * English on a Saudi shop's till.
 *
 * Retail and accounting terms use the wording ZATCA's own Arabic materials use
 * where they have one — فاتورة ضريبية for tax invoice, ضريبة القيمة المضافة for
 * VAT — because a shop reading our screen and reading a ZATCA notice should see
 * the same words. Terms with no official Arabic source are ordinary usage and
 * are listed in the audit as wanting a native reviewer before release.
 */
